from concurrent.futures import ThreadPoolExecutor  # noqa: F401  (used in phase 2)

import pytest


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computing each element in a thread pool.

    The output preserves the order of the input.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(square, xs))


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_basic() -> None:
    assert squares([1, 2, 3]) == [1, 4, 9]


def test_squares_negative_and_zero() -> None:
    assert squares([-4, 0, 5]) == [16, 0, 25]


def test_squares_preserves_order() -> None:
    xs = list(range(-50, 50))
    assert squares(xs) == [x * x for x in xs]


def test_squares_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    snapshot = list(xs)
    squares(xs)
    assert xs == snapshot


@pytest.mark.parametrize("xs", [[7], [1, 1, 1], list(range(200))])
def test_squares_matches_square(xs: list[int]) -> None:
    assert squares(xs) == [square(x) for x in xs]
